def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_my = me[-1]
    last_opp = opp[-1]

    opp_def = n - opp.count('C')
    my_def = n - me.count('C')
    opp_rate = (n - opp_def) / float(n)

    # Consecutive opponent defections
    run_opp_d = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            run_opp_d += 1
        else:
            break

    # Consecutive mutual defections
    run_dd = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D' and me[i] == 'D':
            run_dd += 1
        else:
            break

    recent_len = 10 if n >= 10 else n
    recent = opp[n - recent_len:]
    recent_def = recent_len - recent.count('C')
    recent_rate = (recent_len - recent_def) / float(recent_len)

    short_len = 5 if n >= 5 else n
    short = opp[n - short_len:]
    short_def = short_len - short.count('C')

    # Always cooperator: pure cooperation, probe only in final rounds
    if opp_def == 0:
        remaining = 100 - n
        if remaining <= 2 and n > 0:
            return 'D'
        return 'C'

    # Nearly always cooperator: forgive isolated noise
    if opp_def <= 1 and opp_rate >= 0.9:
        if last_opp == 'D' and run_opp_d >= 2:
            return 'D'
        return 'C'

    # Always defector: exploit only at the very end otherwise defect
    if opp.count('C') == 0:
        remaining = 100 - n
        if remaining <= 1:
            return 'D'
        return 'D' if rng.random() < 0.95 else 'C'

    # Escalating defector: strike back hard if sustained
    if run_opp_d >= 4:
        return 'D'
    if run_opp_d == 3:
        return 'D' if rng.random() < 0.85 else 'C'
    if run_opp_d == 2:
        if short_def >= 3 or recent_def >= 5:
            return 'D' if rng.random() < 0.75 else 'C'
        return 'C' if rng.random() < 0.35 else 'D'

    # Heavy defector overall: defect most, but probe occasionally to unlock gains
    if opp_rate < 0.25:
        if n % 13 == 0:
            return 'C'
        return 'D'

    # Mixed-defector zone
    if opp_rate < 0.5:
        if last_opp == 'D':
            if recent_rate < 0.35:
                return 'D'
            return 'C' if rng.random() < 0.25 else 'D'
        # Opponent cooperated
        if recent_def >= 5:
            return 'D'
        if my_def > n * 0.4:
            return 'C'
        return 'C'

    # Mostly cooperative zone: reciprocal with forgiveness
    if last_opp == 'D':
        if run_dd >= 2:
            # Break mutual defection
            return 'C' if rng.random() < 0.55 else 'D'
        if rng.random() < 0.7:
            return 'D'
        return 'C'

    # Opponent cooperated last
    if last_my == 'D':
        # Build trust back
        return 'C'

    # Probe occasionally against very cooperative opponents
    if opp_rate >= 0.9 and n < 95:
        if n % 19 == 0 and rng.random() < 0.25:
            return 'D'
    elif opp_rate >= 0.75:
        if n % 23 == 0 and rng.random() < 0.12:
            return 'D'

    # Endgame: exploit cooperators in final few rounds
    remaining = 100 - n
    if remaining <= 3 and opp_rate >= 0.5:
        return 'D'

    return 'C'
